const pgState = $('Postgres: Ensure Job Hunter Tables & Seed Vault').first().json || {};
const activePortalSlot = pgState.active_portal_slot || null;
const sentNotifs = new Set(Array.isArray(pgState.sent_notifs) ? pgState.sent_notifs : []);
const eodLogs = Array.isArray(pgState.eod_logs) ? pgState.eod_logs : [];
const existingDrafts = Array.isArray(pgState.followup_drafts) ? pgState.followup_drafts : [];

const jobRows = $('Read Job Application Sheet').all().map(i => i.json);
const refRows = $('Read Reference Sheet').all().map(i => i.json);

const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const CHAT_ID = '8873019272';
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_DOCUMENT_ID/edit';

const _ctx = this;
async function sendTelegram(text, inlineKeyboard) {
  try {
    if (_ctx && _ctx.helpers && typeof _ctx.helpers.httpRequest === 'function') {
      await _ctx.helpers.httpRequest({
        method: 'POST',
        url: `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
        headers: { 'Content-Type': 'application/json' },
        body: {
          chat_id: CHAT_ID,
          text,
          parse_mode: 'Markdown',
          disable_web_page_preview: true,
          ...(inlineKeyboard ? { reply_markup: { inline_keyboard: inlineKeyboard } } : {})
        },
        json: true
      });
      return;
    }
  } catch (e) {}
}

// Build Reference Map by Company Name from Reference Sheet (gid=0)
const refByCompany = {};
const refEmailByCompany = {};
for (const r of refRows) {
  const comp = String(r['Company'] || '').trim().toLowerCase();
  const refName = String(r['Reference'] || r['Name of the person'] || '').trim();
  const refEmail = String(r['Email of Reference'] || '').trim();
  if (comp && refName) {
    refByCompany[comp] = refName;
  }
  if (comp && refEmail) {
    refEmailByCompany[comp] = refEmail;
  }
}

// Helper to infer Company, Industry, Location, Website from JD text when blank
function inferFromJd(title, jd, existingCompany) {
  const text = `${title}\n${jd}`;
  let company = existingCompany;
  if (!company) {
    if (/american express|aexp/i.test(text)) company = 'American Express';
    else if (/siemens energy/i.test(text)) company = 'Siemens Energy';
    else if (/google/i.test(text)) company = 'Google';
    else if (/stripe/i.test(text)) company = 'Stripe';
    else if (/united airlines/i.test(text)) company = 'United Airlines';
    else if (/atlys/i.test(text)) company = 'Atlys';
    else if (/turing/i.test(text)) company = 'Turing';
  }
  let industry = '';
  if (/fintech|financial|bank|card|payment|american express|stripe|principal|crisil/i.test(`${company} ${text}`)) {
    industry = 'Financial Services & FinTech';
  } else if (/energy|siemens|power|industrial/i.test(`${company} ${text}`)) {
    industry = 'Energy & Industrial Technology';
  } else if (/travel|airline|priceline|atlys|united/i.test(`${company} ${text}`)) {
    industry = 'Travel & Aviation Tech';
  } else if (/real estate|jll|jones lang/i.test(`${company} ${text}`)) {
    industry = 'Commercial Real Estate & Advisory';
  } else if (/edtech|university|education/i.test(`${company} ${text}`)) {
    industry = 'Higher Education & EdTech';
  } else if (/retail|7-eleven|ecommerce/i.test(`${company} ${text}`)) {
    industry = 'Retail & E-Commerce';
  } else {
    industry = 'Technology & Data Analytics';
  }

  let location = '';
  if (/gurugram|gurgaon/i.test(text)) location = 'Gurugram (Hybrid)';
  else if (/bengaluru|bangalore/i.test(text)) location = 'Bengaluru';
  else if (/mumbai/i.test(text)) location = 'Mumbai';
  else if (/pune/i.test(text)) location = 'Pune';
  else if (/hyderabad/i.test(text)) location = 'Hyderabad';
  else if (/remote/i.test(text)) location = 'Remote';
  else location = 'India (Hybrid / Remote)';

  let website = '';
  if (company) {
    const slug = company.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (slug.includes('americanexpress')) website = 'https://www.americanexpress.com';
    else if (slug.includes('siemensenergy')) website = 'https://www.siemens-energy.com';
    else website = `https://www.${slug}.com`;
  }
  const about = company
    ? `${company} is a leading ${industry.toLowerCase()} organization hiring for ${title || 'analytics leadership'}.`
    : '';

  return { company, industry, location, website, about };
}

function formatDateMDY(d) {
  return `${d.getMonth() + 1}/${d.getDate()}/${d.getFullYear()}`;
}

function addDaysMDY(dateStr, days) {
  let base = new Date();
  if (dateStr) {
    const parsed = new Date(dateStr);
    if (!isNaN(parsed.getTime())) base = parsed;
  }
  base.setDate(base.getDate() + days);
  return formatDateMDY(base);
}

const sheetUpdates = [];
const newNotifKeys = [];

for (const row of jobRows) {
  const sNo = String(row['S. No.'] || '').trim();
  if (!sNo) continue;

  const title = String(row['Position - Title'] || '').trim();
  const jd = String(row['Position - Description'] || '').trim();
  const comp = String(row['Company'] || '').trim();
  const status = String(row['Status'] || '').trim();

  // Skip completely empty template rows
  if (!title && !jd && !comp && !status) continue;

  const resStatus = String(row['Resume Status'] || '').trim();
  const resLink = String(row['Resume'] || '').trim();
  const existingResumeId = String(row['Resume_id'] || '').trim();

  // MANUAL EDIT PROTECTION GUARD:
  // 1. Never auto-enrich or overwrite a row while the user is still manually filling it out!
  //    Wait until EITHER the user explicitly sets 'Resume Status' = 'Create one', OR all core manual inputs
  //    (Company + Position - Title + full Position - Description >= 100 chars + Status) are present.
  // 2. Once a row already has a Resume_id (already initialized), never overwrite fields the user may have
  //    manually edited or cleared.
  const isReadyForInit = !existingResumeId && (
    resStatus === 'Create one' ||
    (comp !== '' && title !== '' && jd.length >= 100 && status !== '')
  );

  const patch = { 'S. No.': sNo };
  let changed = false;

  const inferred = inferFromJd(title, jd, comp);
  const finalComp = comp || inferred.company || '';

  if (isReadyForInit) {
    patch['Resume_id'] = `RES-${sNo}`;
    changed = true;

    if (!comp && inferred.company) {
      patch['Company'] = inferred.company;
    }
    if (!String(row['Industry'] || '').trim() && inferred.industry) {
      patch['Industry'] = inferred.industry;
    }
    if (!String(row['Location'] || '').trim() && inferred.location) {
      patch['Location'] = inferred.location;
    }
    if (!String(row['Reference'] || '').trim() && finalComp) {
      const refMatch = refByCompany[finalComp.toLowerCase()];
      if (refMatch) {
        patch['Reference'] = refMatch;
      }
    }
    if (status.toLowerCase() === 'applied') {
      const appDate = String(row['Applied On'] || '').trim() || formatDateMDY(new Date());
      if (!String(row['Applied On'] || '').trim()) {
        patch['Applied On'] = appDate;
      }
      if (!String(row['Follow up Date'] || '').trim()) {
        patch['Follow up Date'] = addDaysMDY(appDate, 3);
      }
    }
    if (!String(row['About Company'] || '').trim() && inferred.about) {
      patch['About Company'] = inferred.about;
    }
    if (!String(row['Company website'] || '').trim() && inferred.website) {
      patch['Company website'] = inferred.website;
    }
    if (title && jd.length >= 100 && status.toLowerCase() !== 'applied' && !resStatus && !resLink) {
      patch['Resume Status'] = 'Create one';
    }
  }

  if (changed) {
    sheetUpdates.push(patch);
  }

  // Check if Resume or Cover Letter is 'Ready for Review' and needs Telegram Approval Card (with clickable JD link!)
  const resumeId = String(row['Resume_id'] || patch['Resume_id'] || `RES-${sNo}`).trim();
  const pageLink = String(row['Applied Page link'] || '').trim();
  const jdUrlMatch = jd.match(/https?:\/\/[^\s)]+/i);
  const clickableJdUrl = pageLink || (jdUrlMatch ? jdUrlMatch[0] : (String(row['Company website'] || patch['Company website'] || SHEET_URL).trim() || SHEET_URL));
  const refLabel = String(row['Reference'] || patch['Reference'] || 'Direct / Portal').trim();

  if (resStatus === 'Ready for Review' && resLink) {
    const notifKey = `resume_review:${resumeId}:${resLink.slice(-16)}`;
    if (!sentNotifs.has(notifKey)) {
      const msg =
        `📄 *Stage 1: Tailored Resume Ready for Review*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🏢 *Company:* *${finalComp || 'Target Company'}*\n` +
        `💼 *Role:* ${title || 'Target Role'} (\`${resumeId}\` / Row #${sNo})\n` +
        `🤝 *Reference (Col J):* ${refLabel}\n\n` +
        `🔗 [Click to View Job Description (JD)](${clickableJdUrl})\n` +
        `📥 [Click to Open Tailored 1-Page Resume PDF](${resLink})\n` +
        `📊 [Open Job Application Sheet](${SHEET_URL})\n\n` +
        `_Approve to finalize (or trigger Stage 2 Cover Letter if needed), or tap Rework below:_`;
      await sendTelegram(msg, [
        [{ text: `✅ Approve Only #${sNo} (No Learn)`, callback_data: `apr_nolearn_res:${sNo}` }],
        [{ text: `🧠 Approve & Learn #${sNo}`, callback_data: `apr_res:${sNo}` }],
        [{ text: `📝 Approve + Create CL #${sNo}`, callback_data: `apr_res_cl:${sNo}` }],
        [{ text: `📌 Rework #${sNo} (This Job)`, callback_data: `rwk_res_1:${sNo}` }],
        [{ text: `🧠 Rework #${sNo} (Learn Rule)`, callback_data: `rwk_res_l:${sNo}` }]
      ]);
      newNotifKeys.push({ notif_key: notifKey, s_no: sNo, resume_id: resumeId, notif_type: 'resume_review' });
      sentNotifs.add(notifKey);
    }
  }

  const clStatus = String(row['Cover Letter Status'] || '').trim();
  const clLink = String(row['Cover Letter'] || '').trim();
  if (clStatus === 'Ready for Review' && clLink) {
    const notifKey = `cl_review:${resumeId}:${clLink.slice(-16)}`;
    if (!sentNotifs.has(notifKey)) {
      const msg =
        `📝 *Stage 2: Grounded 1-Page Cover Letter Ready for Review*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🏢 *Company:* *${finalComp || 'Target Company'}*\n` +
        `💼 *Role:* ${title || 'Target Role'} (\`${resumeId}\` / Row #${sNo})\n` +
        `🤝 *Reference (Col J):* ${refLabel}\n\n` +
        `🔗 [Click to View Job Description (JD)](${clickableJdUrl})\n` +
        `📥 [Click to Open 1-Page Cover Letter PDF](${clLink})\n` +
        `📄 [Open Approved Resume PDF](${resLink || SHEET_URL})\n\n` +
        `_Approve to proceed with application submission, or tap Rework below:_`;
      await sendTelegram(msg, [
        [
          { text: '✅ Approve Cover Letter (LGTM)', callback_data: `apr_cl:${sNo}` }
        ],
        [
          { text: '📌 Rework CL (This Job Only)', callback_data: `rwk_cl_1:${sNo}` },
          { text: '🧠 Rework CL (Save to Lessons Learnt)', callback_data: `rwk_cl_l:${sNo}` }
        ]
      ]);
      newNotifKeys.push({ notif_key: notifKey, s_no: sNo, resume_id: resumeId, notif_type: 'cl_review' });
      sentNotifs.add(notifKey);
    }
  }

  // Proactive Referral & HR Follow-Up Reminder on Telegram
  const refVal = String(row['Reference'] || patch['Reference'] || '').trim();
  const hrVal = String(row['HR'] || '').trim();
  const hrEmailVal = String(row['HR Email'] || refEmailByCompany[finalComp.toLowerCase()] || '').trim();
  const isAppliedRow = status.toLowerCase().includes('applied') || status.toLowerCase().includes('submitted');
  if (isAppliedRow && (refVal || hrEmailVal) && !String(row['Notes'] || '').includes('Followed up')) {
    const followDateKey = String(row['Follow up Date'] || patch['Follow up Date'] || 'due').trim();
    const refNotifKey = `referral_followup:${sNo}:${followDateKey}`;
    if (!sentNotifs.has(refNotifKey)) {
      const contactPerson = refVal || hrVal || 'Referrer';
      const firstName = contactPerson.split(/[\/\s,]+/)[0] || 'there';
      const kb = [];
      if (hrEmailVal) {
        kb.push([{ text: `📧 Send Follow-Up Mail to ${hrEmailVal}`, callback_data: `send_ref_mail:job:${sNo}` }]);
      } else {
        kb.push([{ text: `✉️ Add ${firstName}'s Email & Auto-Send Mail`, callback_data: `ref_set_email:${sNo}` }]);
      }
      kb.push([{ text: `💬 View / Copy Follow-Up Message`, callback_data: `ref_card:${sNo}` }]);
      kb.push([{ text: `✅ Mark Followed Up (+5 Days)`, callback_data: `ref_done:${sNo}` }]);

      const remText =
        `🤝 *Referral / HR Follow-Up Reminder (#${sNo})*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
        `🏢 *Company:* *${finalComp}*\n` +
        `💼 *Role:* ${title || 'Target Role'}\n` +
        `👤 *Referrer / Contact:* *${contactPerson}*\n` +
        `📧 *Email:* ${hrEmailVal ? `\`${hrEmailVal}\`` : '_No email on file yet_'}\n` +
        `📅 *Follow-Up Date:* \`${followDateKey}\`\n\n` +
        (hrEmailVal
          ? `_Tap below to send a personalized follow-up email from_ \`user@example.com\` _right now:_`
          : `📋 *Quick Follow-Up Message:*\n\`Hi ${firstName}, hope your week at ${finalComp} is going well! Just wanted to quickly follow up on the ${title || 'role'} I applied for via referral. Please let me know if any additional info is needed from my end!\``);

      await sendTelegram(remText, kb);
      newNotifKeys.push({ notif_key: refNotifKey, s_no: sNo, resume_id: resumeId, notif_type: 'referral_followup' });
      sentNotifs.add(refNotifKey);
    }
  }

}

// Check if triggered by 21:00 IST EOD Schedule or on-demand EOD request
let isEodTrigger = false;
try {
  if ($('EOD Summary Schedule (21:00 IST)').isExecuted) isEodTrigger = true;
} catch (e) {}
const triggerPayload = $input.first()?.json || {};
if (triggerPayload.mode === 'eod') isEodTrigger = true;

if (isEodTrigger) {
  const inPortalJobs = eodLogs.filter(e => e.apply_channel === 'IN_PORTAL');
  const externalJobs = eodLogs.filter(e => e.apply_channel !== 'IN_PORTAL');
  const eodMsg =
    `🌙 *End-of-Day (EOD) Job Hunter Summary*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `⚡ *Applied Inside Portals (Silent Easy/1-Click Apply):* *${inPortalJobs.length}*\n` +
    (inPortalJobs.map(j => `  • *${j.company_name}* — ${j.position_title} _(${j.portal_name})_`).join('\n') || '  • None today') +
    `\n\n🌐 *Applied Outside Portals (Company Career Sites):* *${externalJobs.length}*\n` +
    (externalJobs.map(j => `  • *${j.company_name}* — ${j.position_title} _(${j.portal_name})_`).join('\n') || '  • None today') +
    `\n\n✨ *Half-Filled Rows Auto-Enriched This Run:* *${sheetUpdates.length}*\n` +
    `📧 *Outbound Communication Email:* \`user@example.com\`\n` +
    `📊 [Open Job Application Tracker Sheet](${SHEET_URL})`;

  await sendTelegram(eodMsg, [
    [
      { text: '📊 Live Pipeline', callback_data: 'cmd:pipeline' },
      { text: '📝 Pending Reviews', callback_data: 'cmd:drafts' }
    ],
    [
      { text: '📬 Follow-Up Drafts', callback_data: 'cmd:mail_drafts' },
      { text: '🔐 Credential Vault', callback_data: 'cmd:edit_creds' }
    ]
  ]);
}

return [{
  json: {
    ok: true,
    activePortalSlot,
    executionMode: 'KVM2_SINGLE_PORTAL_ROUND_ROBIN',
    enrichedCount: sheetUpdates.length,
    sheetUpdates,
    newNotifKeys
  }
}];

const data = $('Auto-Enricher, Staged Review Notifier & EOD Engine').first().json || {};
const updates = Array.isArray(data.sheetUpdates) ? data.sheetUpdates : [];
if (updates.length === 0) {
  return [];
}
return updates.map(u => ({ json: u }));
